export function normalizeStackNewlines(stack: string): string {
  return stack.replace(/\r\n?/g, '\n');
}

function linesFor(stack: string, options: NormalizedErrorStackOptions): string[] {
  const value = options.normalizeNewlines ? normalizeStackNewlines(stack) : stack;
  return value.split('\n').map((line, i) => i && options.trimLeadingWhitespace ? line.replace(/^[^\S\r\n]+/, '') : line);
}

function strip(lines: string[], options: NormalizedErrorStackOptions): string[] {
  const mode = options.stripInternalFrames;
  return lines.filter((line, i) => !i || !((mode === 'node' || mode === 'node_and_superjson') && line.includes('node:internal')) && !((mode === 'superjson' || mode === 'node_and_superjson') && /src[\\/]\b(?:transformer|plainer|index)\.ts\b/.test(line)));
}

function redact(lines: string[], options: NormalizedErrorStackOptions): string[] {
  if (options.redactPaths === 'none') return lines;
  const cwd = typeof process !== 'undefined' && typeof process.cwd === 'function' ? process.cwd() : '';
  return lines.map(line => {
    if (options.redactPaths === 'strip_cwd') {
      return cwd ? line.split(cwd + '/').join('').split(cwd + '\\').join('') : line;
    }
    return line.replace(/(?:[A-Za-z]:)?(?:[\\/][^\s():\\/]+)+(?=:\d+|[)\s]|$)/g, path => path.split(/[\\/]/).pop() || path);
  });
}

export function processStackString(stack: string, options: NormalizedErrorStackOptions): string {
  let lines = redact(linesFor(stack, options), options);
  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
  return strip(lines, options).join('\n');
}

export function processStackFrames(stack: string, options: NormalizedErrorStackOptions): { raw: string }[] {
  let lines = redact(strip(linesFor(stack, options), options), options);
  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
  return lines.map(raw => ({ raw }));
}
